65	const AudioAttachmentItem = ({ filename, sourceUrl, mimeType, size, title, compact = false, className }: AudioAttachmentItemProps) => {
66	  const audioRef = useRef<HTMLAudioElement>(null);
67	  const [isPlaying, setIsPlaying] = useState(false);
68	  const [currentTime, setCurrentTime] = useState(0);
69	  const [duration, setDuration] = useState(0);
70	  const [playbackRate, setPlaybackRate] = useState<(typeof AUDIO_PLAYBACK_RATES)[number]>(1);
71	  const displayTitle = title ?? filename;
72	  const fileTypeLabel = getFileTypeLabel(mimeType);
73	  const fileSizeLabel = size ? formatFileSize(size) : undefined;
74	  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;
75	  const currentTimeLabel = formatAudioTime(currentTime);
76	  const durationLabel = getDurationLabel(duration);
77	  const timeLabel = `${currentTimeLabel} / ${durationLabel}`;
78	
79	  useEffect(() => {
80	    if (!audioRef.current) {
81	      return;
82	    }
83	
84	    audioRef.current.playbackRate = playbackRate;
85	  }, [playbackRate]);
86	
87	  const togglePlayback = async () => {
88	    const audio = audioRef.current;
89	
90	    if (!audio) {
91	      return;
92	    }
93	
94	    if (audio.paused) {
95	      try {
96	        await audio.play();
97	      } catch {
98	        setIsPlaying(false);
99	      }
100	      return;
101	    }
102	
103	    audio.pause();
104	  };
105	
106	  const handleSeek = (nextTime: number) => {
107	    const audio = audioRef.current;
108	
109	    if (!audio || Number.isNaN(nextTime)) {
110	      return;
111	    }
112	
113	    audio.currentTime = nextTime;
114	    setCurrentTime(nextTime);
115	  };
116	
117	  const handlePlaybackRateChange = () => {
118	    setPlaybackRate((currentRate) => getNextPlaybackRate(currentRate));
119	  };
120	
121	  const handleDuration = (value: number) => {
122	    setDuration(Number.isFinite(value) ? value : 0);
123	  };
124	
125	  return (
126	    <div className={cn("rounded-xl border border-border/40 bg-background/75", compact ? "px-3 py-2.5" : "px-2 py-1.5", className)}>
127	      <div className="flex items-start justify-between gap-2">
128	        <div className={cn("min-w-0 flex flex-1", compact ? "flex-col gap-0.5" : "items-baseline gap-1")}>
129	          <div className="truncate text-sm font-medium leading-5 text-foreground" title={filename}>
130	            {displayTitle}
131	          </div>
132	          <div className="truncate text-[11px] leading-4 text-muted-foreground">
133	            {fileTypeLabel}
134	            {fileSizeLabel ? ` · ${fileSizeLabel}` : ""}
135	          </div>
136	        </div>
137	
138	        <Button
139	          variant="outline"
140	          size="icon-sm"
141	          onClick={togglePlayback}
142	          aria-label={isPlaying ? `Pause ${displayTitle}` : `Play ${displayTitle}`}
143	        >
144	          {isPlaying ? <PauseIcon className="size-2.5" /> : <PlayIcon className="size-2.5 translate-x-[0.5px]" />}
145	        </Button>
146	      </div>
147	
148	      <div className={cn("mt-1", compact ? "space-y-1.5" : "flex items-center gap-1")}>
149	        <AudioProgressBar
150	          filename={filename}
151	          currentTime={currentTime}
152	          duration={duration}
153	          progressPercent={progressPercent}
154	          onSeek={handleSeek}
155	          className="min-w-0 flex-1"
156	        />
157	
158	        <div className={cn("flex items-center", compact ? "justify-between gap-2" : "shrink-0 gap-1")}>
159	          <div className="shrink-0 text-[10px] tabular-nums text-muted-foreground">{timeLabel}</div>
160	
161	          <Button
162	            variant="ghost"
163	            size="sm"
164	            onClick={handlePlaybackRateChange}
165	            aria-label={`Playback speed ${playbackRate}x for ${displayTitle}`}
166	          >
167	            {playbackRate}x
168	          </Button>
169	        </div>
170	      </div>
171	
172	      <audio
173	        ref={audioRef}
174	        src={sourceUrl}
175	        preload="metadata"
176	        className="hidden"
177	        onLoadedMetadata={(e) => handleDuration(e.currentTarget.duration)}
178	        onDurationChange={(e) => handleDuration(e.currentTarget.duration)}
179	        onTimeUpdate={(e) => setCurrentTime(e.currentTarget.currentTime)}
180	        onPlay={() => setIsPlaying(true)}
181	        onPause={() => setIsPlaying(false)}
182	        onEnded={() => {
183	          setIsPlaying(false);
184	          setCurrentTime(0);
185	        }}
186	      />
187	    </div>
188	  );
189	};
190	
191	export default AudioAttachmentItem;
